=== mapper/Locality ===
package org.springframework.samples.petclinic.mapper;

import java.util.Map;

/**
 * Derives the owner's locality (region). The postcode is preferred: a 4-digit
 * postcode is mapped to its region by range (NSW 2000-2099, VIC 3000-3099,
 * QLD 4000-4099). When the postcode is absent or falls in no known range, it
 * falls back to a fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
 * Brisbane->QLD), or {@code UNKNOWN} when the city is not in the table. The value
 * is a pure function of postcode and city, so it needs no stored state.
 */
public final class Locality {

    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    private static final Map<String, int[]> REGION_RANGE = Map.of(
            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

    private Locality() {
    }

    public static String of(String city) {
        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    }

    public static String of(String postcode, String city) {
        String byPostcode = byPostcode(postcode);
        return byPostcode != null ? byPostcode : of(city);
    }

    private static String byPostcode(String postcode) {
        if (postcode == null || !postcode.matches("[0-9]{4}")) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }
}
=== mapper/HouseholdId ===
package org.springframework.samples.petclinic.mapper;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Derives the stable household identifier shared by owners at the same household,
 * i.e. having the same last name and postcode (last name compared case-insensitively
 * with collapsed whitespace). It is the first 12 hex characters of SHA-256 over
 * {@code normalizedLastName + '|' + postcode}, so every owner in one household resolves
 * to the same id without any stored state.
 */
public final class HouseholdId {

    private HouseholdId() {
    }

    public static String of(String lastName, String postcode) {
        String key = normalize(lastName) + "|" + normalize(postcode);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
=== mapper/IdentityKey ===
package org.springframework.samples.petclinic.mapper;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Derives the single duplicate-detection key for an owner: the SHA-256 hex of
 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. Two owners
 * are duplicates only when their whole identity keys match. Because the telephone is part
 * of the key, two members of one household with different telephones get different keys
 * and are both allowed; only an exact full-key match is a duplicate.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    public static String of(String telephone, String email, String lastName) {
        String key = (telephone == null ? "" : telephone) + "|"
                + (email == null ? "" : email.toLowerCase()) + "|" + Soundex.of(lastName);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}
=== mapper/OwnerSegment ===
package org.springframework.samples.petclinic.mapper;

import java.util.Set;

/**
 * Derives the owner's segment, formatted {@code <TIER>_<AREA>}. TIER is
 * {@code PREMIUM} when the membership level is 3 or more, otherwise {@code STANDARD}.
 * AREA is {@code METRO} when the locality is a known region (NSW, VIC or QLD),
 * otherwise {@code REGIONAL}. The value is a pure function of level and locality.
 */
public final class OwnerSegment {

    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");

    private OwnerSegment() {
    }

    public static String of(int membershipLevel, String locality) {
        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
        String area = METRO_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
        return tier + "_" + area;
    }
}

