package org.springframework.samples.petclinic.mapper;

import org.mapstruct.AfterMapping;
import org.mapstruct.MappingTarget;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerIdentityDto;
import org.springframework.samples.petclinic.rest.function.owner.HouseholdTier;
import org.springframework.stereotype.Component;

/**
 * Fills the derived {@code membershipPoints} and {@code membershipLevel} on every owner
 * DTO. It needs the {@link OwnerRepository} to size the household, so it runs as a
 * MapStruct {@code @AfterMapping} step wired into {@code OwnerMapper} rather than as a
 * static expression.
 */
@Component
public class MembershipDecorator {

    @Autowired
    private OwnerRepository ownerRepository;

    @AfterMapping
    public void addMembership(Owner owner, @MappingTarget OwnerDto dto) {
        boolean goldHousehold = HouseholdTier.isGold(owner, ownerRepository);
        int points = MembershipPoints.of(owner.getNamesakeCount(), owner.getEmail(),
                owner.getRegistrationDate(), goldHousehold);
        dto.setMembershipPoints(points);
        dto.setMembershipLevel(HouseholdCap.cap(owner, MembershipLevel.of(points), ownerRepository));
        dto.setOwnerSegment(OwnerSegment.of(dto.getMembershipLevel(), dto.getLocality()));
    }
}

package org.springframework.samples.petclinic.mapper;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Derives the stable household identifier shared by owners at the same household,
 * i.e. having the same last name and postcode (last name compared case-insensitively
 * with collapsed whitespace). It is the first 12 hex characters of SHA-256 over
 * {@code normalizedLastName + '|' + postcode}, so every owner in one household resolves
 * to the same id without any stored state.
 */
public final class HouseholdId {

    private HouseholdId() {
    }

    public static String of(String lastName, String postcode) {
        String key = normalize(lastName) + "|" + normalize(postcode);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

package org.springframework.samples.petclinic.mapper;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Derives the single duplicate-detection key for an owner: the SHA-256 hex of
 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. Two owners
 * are duplicates only when their whole identity keys match. Because the telephone is part
 * of the key, two members of one household with different telephones get different keys
 * and are both allowed; only an exact full-key match is a duplicate.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    public static String of(String telephone, String email, String lastName) {
        String key = (telephone == null ? "" : telephone) + "|"
                + (email == null ? "" : email.toLowerCase()) + "|" + Soundex.of(lastName);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.CheckDigit;
import org.springframework.samples.petclinic.mapper.FiscalYear;
import org.springframework.samples.petclinic.mapper.Locality;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code memberId} formatted {@code <REGION><FY><HASH8><CHK>}: the region
 * derived from the postcode, the two-digit fiscal year of the registration date, the first 8
 * upper-case hex characters of the SHA-256 of the normalized telephone concatenated with the
 * last name, and a single Luhn check digit over the digits of the preceding segments. It is a
 * pure function of the owner's own fields, so it needs no repository lookup.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner) {
        String region = Locality.of(owner.getPostcode(), owner.getCity());
        String fiscalYear = String.format("%02d", FiscalYear.of(owner.getRegistrationDate()) % 100);
        String hash8 = hash8(owner.getTelephone() + owner.getLastName());
        String base = region + fiscalYear + hash8;
        owner.setCustomerCode(base + CheckDigit.of(base));
    }

    private static String hash8(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 4; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.concurrent.atomic.AtomicLong;

import net.officefloor.plugin.variable.Val;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.samples.petclinic.mapper.MembershipLevel;
import org.springframework.samples.petclinic.mapper.MembershipPoints;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

public class SaveOwner {

    private static final Logger audit = LoggerFactory.getLogger("AUDIT");

    private static final Logger notify = LoggerFactory.getLogger("NOTIFY");

    private static final AtomicLong EVENT_SEQ = new AtomicLong();

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        ownerRepository.save(owner);
        int membershipLevel = MembershipLevel.of(MembershipPoints.of(owner.getNamesakeCount(),
                owner.getEmail(), owner.getRegistrationDate(), HouseholdTier.isGold(owner, ownerRepository)));
        // Unified primary identifier of the owner.
        String memberId = owner.getCustomerCode();
        audit.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
                owner.getId(), memberId, owner.getRegistrationDate(), membershipLevel);
        audit.info(String.format(
                "{\"seq\":%d,\"ownerId\":%d,\"memberId\":\"%s\",\"membershipLevel\":%d,\"event\":\"OWNER_CREATED\"}",
                EVENT_SEQ.incrementAndGet(), owner.getId(), memberId, membershipLevel));
        notify.info("welcome owner id={} memberId={}", owner.getId(), memberId);
    }
}

